import XCTest
@testable import Screener

/// InputController against `input.json` (generated by driving the reference's
/// proxy/input.py InputController with a capturing cipher; see
/// Tools/fixtures/README.md), plus the view → host mapping and scroll curves.
@MainActor
final class InputControllerTests: XCTestCase {
    /// Records every message handed to the control channel, in order.
    private final class Sink: @unchecked Sendable {
        private let lock = NSLock()
        private var _sent: [Data] = []
        func append(_ d: Data) { lock.withLock { _sent.append(d) } }
        var sent: [Data] { lock.withLock { _sent } }
    }

    private var fixture: [String: Any] = [:]
    private var key = Data()

    override func setUp() async throws {
        fixture = try Fixture.load("input")
        key = Data(hex: try XCTUnwrap(fixture["cbc_key"] as? String))
    }

    private func expected(_ name: String) throws -> [String] {
        let entry = try XCTUnwrap(fixture[name] as? [String: Any], name)
        return try XCTUnwrap(entry["result"] as? [String], name)
    }

    private func make(_ w: Int = 1920, _ h: Int = 1080, key: Data? = nil) -> (InputController, Sink) {
        let sink = Sink()
        let c = InputController(contentKey: key ?? self.key, serverWidth: w, serverHeight: h,
                                send: { sink.append($0) })
        return (c, sink)
    }

    // MARK: wire bytes vs the reference

    func testClickMatchesReference() async throws {
        let (c, sink) = make()
        c.pointer(buttons: 0, x: 960, y: 540)
        c.pointer(buttons: 1, x: 960, y: 540)
        c.pointer(buttons: 0, x: 960, y: 540)
        await c.flush()
        XCTAssertEqual(sink.sent.map(\.hex), try expected("click"))
    }

    func testRightClickMatchesReference() async throws {
        let (c, sink) = make()
        c.pointer(buttons: 2, x: 10, y: 20)
        c.pointer(buttons: 0, x: 10, y: 20)
        await c.flush()
        XCTAssertEqual(sink.sent.map(\.hex), try expected("right_click"))
    }

    func testClampMatchesReference() async throws {
        let (c, sink) = make()
        c.pointer(buttons: 0, x: -5, y: 5000)
        c.pointer(buttons: 0, x: 1920, y: 1080)
        await c.flush()
        XCTAssertEqual(sink.sent.map(\.hex), try expected("clamp"))
    }

    func testSetServerDimsMatchesReference() async throws {
        let (c, sink) = make()
        c.setServerDims(width: 3840, height: 2160)
        c.pointer(buttons: 0, x: 3000, y: 2000)
        await c.flush()
        XCTAssertEqual(sink.sent.map(\.hex), try expected("set_server_dims"))
    }

    func testScrollMatchesReference() async throws {
        let (c, sink) = make()
        c.scroll(x: 100, y: 200, dy: 2)
        await c.flush()
        XCTAssertEqual(sink.sent.map(\.hex), try expected("scroll_down_2"))

        let (c2, sink2) = make()
        c2.scroll(x: 100, y: 200, dy: -1)
        c2.scroll(x: 100, y: 200, dy: 0)
        await c2.flush()
        XCTAssertEqual(sink2.sent.map(\.hex), try expected("scroll_up_1"))
        XCTAssertEqual(try expected("scroll_horizontal_only"), [])
    }

    func testKeysMatchReference() async throws {
        let (c, sink) = make()
        c.key(down: true, keysym: 0xffeb)
        c.key(down: true, keysym: 0x63)
        c.key(down: false, keysym: 0x63)
        c.key(down: false, keysym: 0xffeb)
        c.key(down: true, keysym: 0)
        await c.flush()
        XCTAssertEqual(sink.sent.map(\.hex), try expected("keys"))
    }

    func testWithoutAContentKeyPointerEventsArePlainRFB() async {
        let sink = Sink()
        let c = InputController(contentKey: nil, serverWidth: 1920, serverHeight: 1080, send: { sink.append($0) })
        c.pointer(buttons: 1, x: 100, y: 200)
        await c.flush()
        XCTAssertEqual(sink.sent.map(\.hex), ["0501006400c8"])
    }

    func testClosedControllerSendsNothing() async {
        let (c, sink) = make()
        c.close()
        c.pointer(buttons: 1, x: 1, y: 1)
        c.key(down: true, keysym: 0x61)
        await c.flush()
        XCTAssertEqual(sink.sent, [])
    }

    // MARK: coalescing

    func testMovesCoalesceWhileASendIsInFlightButButtonsNeverDo() async throws {
        let gate = Gate()
        let sink = Sink()
        let c = InputController(contentKey: nil, serverWidth: 1920, serverHeight: 1080, send: { d in
            await gate.wait()
            sink.append(d)
        })
        c.pointer(buttons: 0, x: 1, y: 1, coalescable: true)      // in flight (parked)
        await Task.yield()
        c.pointer(buttons: 0, x: 2, y: 2, coalescable: true)
        c.pointer(buttons: 0, x: 3, y: 3, coalescable: true)      // replaces (2,2)
        c.pointer(buttons: 1, x: 3, y: 3)                         // a click: kept
        c.pointer(buttons: 1, x: 4, y: 4, coalescable: true)
        c.pointer(buttons: 1, x: 5, y: 5, coalescable: true)      // replaces (4,4)
        c.pointer(buttons: 0, x: 5, y: 5)
        await gate.open()
        await c.flush()
        let xs = sink.sent.map { Int($0[2]) << 8 | Int($0[3]) }
        let buttons = sink.sent.map { Int($0[1]) }
        XCTAssertEqual(xs, [1, 3, 3, 5, 5])
        XCTAssertEqual(buttons, [0, 0, 1, 1, 0])
    }

    // MARK: view → host mapping (app.py to_canvas over an aspect-fit canvas)

    func testCentreOfA1376x1032ViewMapsToTheCentreOf1920x1080() {
        let (c, _) = make()
        let view = CGSize(width: 1376, height: 1032)
        let p = c.hostPoint(forViewPoint: CGPoint(x: 688, y: 516), viewSize: view)
        XCTAssertEqual(p?.x, 960)
        XCTAssertEqual(p?.y, 540)
    }

    func testLetterboxPointsClampToTheEdge() {
        let (c, _) = make()
        let view = CGSize(width: 1376, height: 1032)
        // 1920x1080 fits as 1376x774 at y = 129…903.
        let top = c.hostPoint(forViewPoint: CGPoint(x: 688, y: 10), viewSize: view)
        XCTAssertEqual(top?.x, 960)
        XCTAssertEqual(top?.y, 0)
        let bottom = c.hostPoint(forViewPoint: CGPoint(x: 1376, y: 1031), viewSize: view)
        XCTAssertEqual(bottom?.x, 1919)
        XCTAssertEqual(bottom?.y, 1079)
        let topLeft = c.hostPoint(forViewPoint: CGPoint(x: 0, y: 129), viewSize: view)
        XCTAssertEqual(topLeft?.x, 0)
        XCTAssertEqual(topLeft?.y, 0)
        XCTAssertNil(c.hostPoint(forViewPoint: .zero, viewSize: .zero))
    }

    func testPillarboxMapping() {
        let (c, _) = make(2752, 2064)
        // 4:3 canvas in a 16:9 view → bars left and right.
        let view = CGSize(width: 1600, height: 900)
        let fitWidth = 900.0 * 2752 / 2064               // 1200
        let left = (1600 - fitWidth) / 2                 // 200
        XCTAssertEqual(c.hostPoint(forViewPoint: CGPoint(x: 100, y: 450), viewSize: view)?.x, 0)
        XCTAssertEqual(c.hostPoint(forViewPoint: CGPoint(x: left + fitWidth / 4, y: 450), viewSize: view)?.x, 688)
        XCTAssertEqual(c.hostPoint(forViewPoint: CGPoint(x: 1590, y: 450), viewSize: view)?.x, 2751)
    }

    // MARK: scroll curves

    func testWheelAccumulatorPortsTheReferenceCurve() {
        var w = WheelScroll()
        XCTAssertEqual(w.ticks(wheelDelta: 1, atMilliseconds: 1000), -12)       // slow notch: ×12, up
        XCTAssertEqual(w.ticks(wheelDelta: 0.05, atMilliseconds: 1500), 0)      // sub-tick: carried
        XCTAssertEqual(w.ticks(wheelDelta: 0.05, atMilliseconds: 1510), -6)     // -0.6 - 6 = -6.6
        XCTAssertEqual(w.ticks(wheelDelta: -30, atMilliseconds: 1520), 50)      // clamp 200, emit ≤ 50
        XCTAssertEqual(w.ticks(wheelDelta: -0.001, atMilliseconds: 1530), 50)   // carry 150 → 50
        XCTAssertEqual(w.ticks(wheelDelta: 0, atMilliseconds: 1540), 0)         // dy == 0 ignored
    }

    func testWheelAccelerationSteps() {
        let gaps: [(Double, Int)] = [(10, -10 * 12), (30, -6 * 12), (60, Int(-3.5 * 12)), (150, -2 * 12),
                                     (300, Int((-1.4 * 12).rounded(.towardZero))), (400, -12)]
        for (gap, want) in gaps {
            var w = WheelScroll(lastMilliseconds: 10_000)
            let got = w.ticks(wheelDelta: 1, atMilliseconds: 10_000 + gap)
            XCTAssertEqual(got, max(-50, want), "gap \(gap)")
        }
    }

    func testPixelScrollFollowsTheFingers() {
        var s = PixelScroll()
        XCTAssertEqual(s.ticks(points: 10, ticksPerPoint: 1), -10)    // fingers down → content down → scroll up
        XCTAssertEqual(s.ticks(points: -0.4, ticksPerPoint: 1), 0)
        XCTAssertEqual(s.ticks(points: -0.7, ticksPerPoint: 1), 1)    // 0.4 + 0.7 = 1.1
        XCTAssertEqual(s.ticks(points: -500, ticksPerPoint: 1), 50)   // emit ≤ 50, carry up to 200
        XCTAssertEqual(s.ticks(points: 0, ticksPerPoint: 1), 50)
    }

    func testHostScrollScaleIsLogicalPixelsPerViewPoint() {
        let (c, _) = make(2752, 2064)
        c.pointScale = 2
        // 2752x2064 backing = 1376x1032 logical shown in a 1376x1032 view → 1:1.
        XCTAssertEqual(c.scrollTicksPerPoint(viewSize: CGSize(width: 1376, height: 1032)), 1, accuracy: 1e-9)
        XCTAssertEqual(c.scrollTicksPerPoint(viewSize: CGSize(width: 688, height: 516)), 2, accuracy: 1e-9)
    }
}

/// Parks callers until opened.
actor Gate {
    private var isOpen = false
    private var waiters: [CheckedContinuation<Void, Never>] = []
    func wait() async {
        if isOpen { return }
        await withCheckedContinuation { waiters.append($0) }
    }
    func open() {
        isOpen = true
        waiters.forEach { $0.resume() }
        waiters.removeAll()
    }
}
